jQuery('body').on('click keyup', '[action-remove-from-resume-watching]', function (e) {
    var time_out = false;
    var t = jQuery(this);
    if (t.closest('.resume-watching-list').length > 0) {
        if (t.closest('.resume-watching-list').siblings('.load_more_btn').length > 0 && jQuery('#load-more-btn').length > 0 && !jQuery('#load-more-btn').hasClass('disabled-link')
        ) {
            var tt = t.closest('.resume-watching-list').siblings('.load_more_btn');
            if (tt.children('[data-load-more]').length > 0 && tt.children('[data-load-more]').filter(':visible').length > 0){
                loadMoreData();
                time_out = true;
            }

        }
    }
    if(time_out){
        setTimeout(function() {
            hide_resume_watching(t);
        }, 1000);
    }else{
        hide_resume_watching(t);
    }

    return false;
});

function hide_resume_watching(t){
    jQuery.post("https://ayn.om/hide_from_resume_watching", {
        show_id: t.data('id'),
        _token: 'hraXJOUbcbos7h6Y7bsIhBUywvBIB1IRyvQHrjC5'
    }).done(function (data) {
        if (data['status']) {
            if (t.closest('.resume-watching-carousel').length> 0) {
                t.closest('.owl-item').remove();
                if ($('.resume-watching-carousel .owl-stage').is(':empty')) {
                    $('.resume-watching').remove();
                }
            }

            if (t.closest('.resume-watching-list').length > 0) {
                t.closest('.items').remove();
            }

            return false;
        } else {
            alert(data['message']);
        }
    });
}

function liveEmbedRadio(audio_id){
    // var t = $('[data-live-embed-radio]');
    // if(!t.hasClass('live-embed-loading')) {
    jQuery.ajax({
        type: "GET",
        url: "https://ayn.om/get_full_audio_url",
        data: {
            audio_id: audio_id,
        },
        beforeSend: function(){

        },
        complete: function(){
        },
        success: function(data){
            if(data['status'] && (data['embed'])){
                $( "#popup_modal" ).html( data['embed'] );
                // jQuery('#alert-player').addClass('show');
            }else if(data['show_vip_popup']){
                $( "#popup_modal" ).html('');
