            }
        });
        return false;
    });

    let timeout_auto_complete;

    function search_auto_complete(value){
        current_request = jQuery.ajax({
            type: "GET",
            url: "https://ayn.om/search-auto-complete",
            data: {
                text: value,
                page: 1
            }, // serializes the form's elements.
            dataType: 'json',
            beforeSend: function () {
                $(".search-results").html('');
                $('.loading').css('display', 'block');
                $(".previous-searches").hide();
            },
            complete: function () {

            },
            success: function (data) {
                $('.loading').css('display', 'none');
                if(data['html']){
                    $(".search-dropdown").show();
                    $(".search-results").show();
                    $('.search-results').html(data['html']);
                }else{
                    $(".search-dropdown").hide();
                    $(".search-results").hide();
                }

            }
        });

    }

    function handleAutoComplete(value) {
        // 1. Clear the existing timer
        clearTimeout(timeout_auto_complete);

        // 2. Start a new 500ms timer
        timeout_auto_complete = setTimeout(() => {
            search_auto_complete(value);
        }, 500);
    }
    function save_history(id,type,url='',text=''){
        current_request = jQuery.ajax({
            type: "POST",
            url: "https://ayn.om/search-history",
            data: {
                id: id,
                type:type,
                text:text,
                _token : 'hraXJOUbcbos7h6Y7bsIhBUywvBIB1IRyvQHrjC5'
            }, // serializes the form's elements.
            dataType: 'json',
            beforeSend: function () {

            },
            complete: function () {

            },
            success: function (data) {
                if(url !== ''){
                    window.location.href = url;
                }

            }
        });
    }
    $(document).on("click", "[data-search-action]", function() {
        var url = $(this).data('href');
        var id = $(this).data('id');
        var type = $(this).data('type');
        var text = '';
        if($(this).attr('data-history') === undefined){
            text = $('#inputSearchTerm').val();
        }
        save_history(id,type,url,text);

    });

    $(document).on("click", "[data-delete-search-history-action]", function(e) {
        e.stopPropagation();
        let t = $(this);
        var id = t.data('id');
        if(!t.hasClass('disable')){
            jQuery.ajax({
                type: "POST",
                url: "https://ayn.om/delete-search-history",
                data: {
                    id: id,
                    _token : 'hraXJOUbcbos7h6Y7bsIhBUywvBIB1IRyvQHrjC5'
                }, // serializes the form's elements.
                dataType: 'json',
                beforeSend: function () {
                    t.addClass('disable');
                },
                complete: function () {

                },
                success: function (data) {
                    t.removeClass('disable');
                    if(data.success){
                        t.parent('.p-search-item').remove();
                    }
                },
                error: function (){
                    t.removeClass('disable');
                }
            });
        }


    });



    // typing
    $("#inputSearchTerm").on("input", function () {

        var value = $(this).val().trim();

        if (value.length > 0) {
            var val = value.replace(/\s+/g, '');
            if (val.length >= 3) {
                handleAutoComplete(value);

            }
        } else {
                    }

    });

jQuery(document).ready(function ($) {
        // input focus
        $("#inputSearchTerm").on("focus", function () {
                        if ($('#inputSearchTerm').val() != '') {
                handleAutoComplete($("#inputSearchTerm").val());
            }
            $(".search-results").html('');
        });

    // click outside close
    $(document).on("click", function (e) {

        if (!$(e.target).closest("#inputSearchTerm, .search-dropdown").length) {
            $(".search-dropdown").hide();
        }

    });
});
